// GitHub Auditor — filtre les repos actifs et construit le payload Ollama
const items = $input.all().flatMap(i => i.json);
const results = [];
// Le system prompt complet « Architecte Collaborateur » est tronqué ici pour lisibilité.
// Voir le README.md pour le texte intégral.
const system = "Tu es un IA expert, un \"Architecte Collaborateur\" de code. [...]";

for (const repo of items) {
  if (repo.archived === true || repo.disabled === true) continue;
  if (!repo.permissions || (!repo.permissions.push && !repo.permissions.admin)) continue;

  const meta = {
    name: repo.name || '',
    full_name: repo.full_name || '',
    desc: repo.description || '(aucune description)',
    lang: repo.language || 'Non spécifié',
    topics: (repo.topics && repo.topics.length) ? repo.topics.join(', ') : 'Aucun',
    pushed: repo.pushed_at ? repo.pushed_at.slice(0,10) : 'Inconnu',
    created: repo.created_at ? repo.created_at.slice(0,10) : 'Inconnu',
    issues: repo.open_issues_count || 0,
    branch: repo.default_branch || 'main',
    visibility: repo.private ? 'Privé' : 'Public',
    size: repo.size ? Math.round(repo.size / 1024) + ' Mo' : 'Inconnu',
  };

  const user = `Analyse le dépôt GitHub suivant et fournis un rapport d'audit complet.\n\n**Dépôt :** ${meta.full_name}\n**Description :** ${meta.desc}\n**Langage principal :** ${meta.lang}\n**Sujets / Topics :** ${meta.topics}\n**Visibilité :** ${meta.visibility}\n**Branche par défaut :** ${meta.branch}\n**Taille estimée :** ${meta.size}\n**Créé le :** ${meta.created}\n**Dernier push :** ${meta.pushed}\n**Problèmes ouverts :** ${meta.issues}\n\nRédige le rapport en suivant le format prescrit.`;

  const payload = {
    model: 'qwen2.5:3b',
    stream: false,
    keep_alive: 0,
    options: { num_ctx: 8192, temperature: 0.3, num_predict: 800 },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user }
    ]
  };

  results.push({
    json: {
      repo_name: meta.full_name,
      repo_desc: meta.desc,
      repo_visibility: meta.visibility,
      repo_lang: meta.lang,
      ollama_body: JSON.stringify(payload)
    }
  });
}
return results;

const item = $input.first().json || {};
const meta = $('Filtrer et préparer l\'analyse').item.json;
const repoName = meta ? meta.repo_name : 'Repo inconnu';

let analysis = '';
if (item.message && item.message.content) {
  analysis = item.message.content.trim();
} else if (item.response && item.response.message && item.response.message.content) {
  analysis = item.response.message.content.trim();
} else if (typeof item === 'object') {
  analysis = JSON.stringify(item).slice(0, 2000);
}

if (analysis.length > 4000) {
  analysis = analysis.slice(0, 3997) + '...';
}

const header = `\ud83e\uddd1\u200d\ud83d\udcbb Audit GitHub : ${repoName}`;
const message = `${header}\n\n${analysis}`;

if (message.length > 4096) {
  return [{ json: { analysis: `${header}\n\nRapport trop long, voici le début :\n\n${analysis.slice(0, 3600)}` } }];
}
return [{ json: { analysis: message } }];
